	/** 
	 * jumpstart the process by instantiating2 User
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		userId = UserService.getUserInstance()
		.createUser( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		UserService.getUserInstance()
				.createUser( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.userSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for User : " + successValue.getUserId());
							  if (successValue.getUserId().equals(userId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfUserList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("User test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on user consumed")
					);
			subscriber.userSubscribe( userId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for User : " + successValue.getUserId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfUserList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on user for userId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a User. 
	 */
	protected User read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created User" );

		User entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read User with primary key" );
		msg.append( userId );
		
		UserFetchOneSummary fetchOneSummary = new UserFetchOneSummary( userId );

		try {
			entity = UserService.getUserInstance().getUser( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found User " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a User.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a User." );

		StringBuilder msg = new StringBuilder( "Failed to update a User : " );        
		User entity = read();
		UpdateUserCommand command = generateUpdateCommand();
		command.setUserId(entity.getUserId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created User." );

			// for use later on...
			userId = entity.getUserId();

			UserService proxy = UserService.getUserInstance();  

			proxy.updateUser( command ).get();

			LOGGER.info( "-- Successfully saved User - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + userId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a User.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created User." );

		User entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read User with id " + userId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read User with id " + userId );

			throw e;
		}

		try{
			UserService.getUserInstance().delete( new DeleteUserCommand( entity.getUserId() ) ).get();
			LOGGER.info( "-- Successfully deleted User with id " + userId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete User with id " + userId );

			throw e;
		}
	}

	/**
	 * get all Users.
	 */
	protected List<User> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Users:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all User : " );        
		List<User> collection  = new ArrayList<>();

		try {
			// call the static get method on the UserService
			collection = UserService.getUserInstance().getAllUser();
			assertNotNull( collection, "An Empty collection of User was incorrectly returned.");
			
			// Now print out the values
			User entity = null;            
			Iterator<User> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getUserId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

